const byLevel = new Map(boards.map(board => [board.id, board]));
export const DIVERSE_SURFACE_LEVEL_COUNT = boards.length;
export function createDiverseSurfaceLevel(level) {
  const board = byLevel.get(level);
  if (!board) throw new RangeError('Diverse surface level must be between 4 and 100');
  return unpackCampaignBoard(board);
}
